  function Contact() {
    return (
      <div className="max-w-2xl mx-auto">
        <h1 className="text-4xl font-bold mb-4">Contact Us</h1>
        <p className="text-gray-600 mb-6">
          Have questions? We'd love to hear from you.
        </p>
